<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->query("SELECT q.id,q.title,q.duration_minutes,q.open_at,q.close_at,s.name subject FROM quizzes q JOIN subjects s ON s.id=q.subject_id WHERE q.status='Published' ORDER BY q.id DESC");page_top('Quiz Center');?><div class="card p-4"><table class="table"><tr><th>Quiz</th><th>Subject</th><th>Duration</th><th>Window</th><th>Action</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['duration_minutes'])?> min</td><td><?=e($r['open_at'])?> → <?=e($r['close_at'])?></td><td><a class="btn btn-sm btn-primary" href="quiz_take.php?id=<?=e($r['id'])?>">Attempt</a></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>